import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
// Min reduction over the middle dimension of a contiguous 3D-like layout.
// Input viewed as [outer, R, inner]; output is [outer, inner].
// out[b, n] = min over r of in[b*R*inner + r*inner + n]
// Optimization: vectorized 128-bit global loads. Each thread reduces 4
// consecutive inner columns (4 independent accumulators) and uses
// ld.global.v4.f32 whenever the row pointer is 16-byte aligned, with a
// predicated 4x scalar fallback otherwise, quadrupling the bytes moved
// per memory instruction in this DRAM-bound streaming pass. The row
// alignment predicates are loop-invariant because the 4-row unrolled
// pointer advance is 16*inner bytes (0 mod 16), and the grid-stride
// persistent launch over (outer, n-tile) work items is preserved.
.visible .entry min_reduce_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 outer,
    .param .u32 R,
    .param .u32 inner
)
{
    .reg .pred %p<14>;
    .reg .b32 %r<32>;
    .reg .b64 %rd<16>;
    .reg .f32 %f<24>;
    // load kernel parameters once (invariant across work items)
    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u32 %r7, [outer];
    ld.param.u32 %r8, [R];
    ld.param.u32 %r6, [inner];
    mov.u32 %r2, %ntid.x;             // blockDim.x
    mov.u32 %r4, %tid.x;
    shl.b32 %r3, %r2, 2;              // columns per block = blockDim.x*4
    // tiles_x = ceil(inner / columns_per_block)
    add.u32 %r17, %r6, %r3;
    sub.u32 %r17, %r17, 1;
    div.u32 %r18, %r17, %r3;          // tiles_x
    mul.lo.u32 %r19, %r7, %r18;       // total work items = outer * tiles_x
    // w = ctaid.y * nctaid.x + ctaid.x ; step = nctaid.x * nctaid.y
    mov.u32 %r20, %nctaid.x;
    mov.u32 %r21, %nctaid.y;
    mul.lo.u32 %r22, %r20, %r21;      // grid-stride step
    mov.u32 %r23, %ctaid.y;
    mul.lo.u32 %r24, %r23, %r20;
    mov.u32 %r1, %ctaid.x;
    add.u32 %r24, %r24, %r1;          // w = first work item for this CTA
    // row stride in bytes = inner*4 (loop-invariant)
    mul.wide.u32 %rd5, %r6, 4;
    add.u64 %rd8, %rd5, %rd5;         // 2*stride
    add.u64 %rd9, %rd8, %rd5;         // 3*stride
    add.u64 %rd10, %rd8, %rd8;        // 4*stride
WORK_LOOP:
    setp.ge.u32 %p1, %r24, %r19;
    @%p1 bra DONE;                    // no work items left
    // b = w / tiles_x ; tile = w % tiles_x ; n0 = (tile*blockDim.x+tid)*4
    div.u32 %r9, %r24, %r18;          // b
    rem.u32 %r25, %r24, %r18;         // tile
    mul.lo.u32 %r26, %r25, %r2;
    add.u32 %r26, %r26, %r4;          // thread column-group index
    shl.b32 %r5, %r26, 2;             // n0 = first column of this thread
    setp.ge.u32 %p2, %r5, %r6;
    @%p2 bra NEXT_WORK;               // bounds check for partial tiles
    // p3 = full 4-column group (n0+4 <= inner)
    add.u32 %r27, %r5, 4;
    setp.le.u32 %p3, %r27, %r6;
    // per-lane valid predicates for ragged groups and stores
    add.u32 %r28, %r5, 1;
    setp.lt.u32 %p4, %r28, %r6;       // lane 1 valid
    add.u32 %r29, %r5, 2;
    setp.lt.u32 %p5, %r29, %r6;       // lane 2 valid
    add.u32 %r30, %r5, 3;
    setp.lt.u32 %p6, %r30, %r6;       // lane 3 valid
    // base element offset = b*R*inner + n0
    mul.lo.u32 %r10, %r9, %r8;
    mul.lo.u32 %r11, %r10, %r6;
    add.u32 %r12, %r11, %r5;
    // running pointers = in_ptr + (base + k*inner)*4
    mul.wide.u32 %rd3, %r12, 4;
    add.u64 %rd4, %rd1, %rd3;         // p0
    add.u64 %rd11, %rd4, %rd5;        // p1
    add.u64 %rd12, %rd4, %rd8;        // p2
    add.u64 %rd13, %rd4, %rd9;        // p3
    // four independent accumulators (one per column) = +inf
    mov.f32 %f1, 0f7F800000;
    mov.f32 %f2, 0f7F800000;
    mov.f32 %f3, 0f7F800000;
    mov.f32 %f4, 0f7F800000;
    @!%p3 bra PARTIAL_THREAD;         // ragged group: scalar path
    // Row alignment predicates are loop-invariant: the 4-row pointer
    // advance is 16*inner bytes (0 mod 16), so each row's alignment
    // repeats every 4 rows.
    and.b64 %rd14, %rd4, 15;
    setp.eq.u64 %p8, %rd14, 0;        // row 0 mod 4 is 16B aligned
    and.b64 %rd14, %rd11, 15;
    setp.eq.u64 %p9, %rd14, 0;        // row 1 mod 4 is 16B aligned
    and.b64 %rd14, %rd12, 15;
    setp.eq.u64 %p10, %rd14, 0;       // row 2 mod 4 is 16B aligned
    and.b64 %rd14, %rd13, 15;
    setp.eq.u64 %p11, %rd14, 0;       // row 3 mod 4 is 16B aligned
    mov.u32 %r13, 0;                  // r = 0
    and.b32 %r14, %r8, 0xFFFFFFFC;    // R rounded down to multiple of 4
UNROLL_LOOP:
    setp.lt.u32 %p7, %r13, %r14;
    @!%p7 bra REM_LOOP;
    // issue all 4 row loads back to back (vector when aligned)
    @!%p8 ld.global.f32 %f5, [%rd4];
    @!%p8 ld.global.f32 %f6, [%rd4+4];
    @!%p8 ld.global.f32 %f7, [%rd4+8];
    @!%p8 ld.global.f32 %f8, [%rd4+12];
    @%p8 ld.global.v4.f32 {%f5, %f6, %f7, %f8}, [%rd4];
    @!%p9 ld.global.f32 %f9, [%rd11];
    @!%p9 ld.global.f32 %f10, [%rd11+4];
    @!%p9 ld.global.f32 %f11, [%rd11+8];
    @!%p9 ld.global.f32 %f12, [%rd11+12];
    @%p9 ld.global.v4.f32 {%f9, %f10, %f11, %f12}, [%rd11];
    @!%p10 ld.global.f32 %f13, [%rd12];
    @!%p10 ld.global.f32 %f14, [%rd12+4];
    @!%p10 ld.global.f32 %f15, [%rd12+8];
    @!%p10 ld.global.f32 %f16, [%rd12+12];
    @%p10 ld.global.v4.f32 {%f13, %f14, %f15, %f16}, [%rd12];
    @!%p11 ld.global.f32 %f17, [%rd13];
    @!%p11 ld.global.f32 %f18, [%rd13+4];
    @!%p11 ld.global.f32 %f19, [%rd13+8];
    @!%p11 ld.global.f32 %f20, [%rd13+12];
    @%p11 ld.global.v4.f32 {%f17, %f18, %f19, %f20}, [%rd13];
    // advance the 4 row pointers by 4 rows
    add.u64 %rd4, %rd4, %rd10;
    add.u64 %rd11, %rd11, %rd10;
    add.u64 %rd12, %rd12, %rd10;
    add.u64 %rd13, %rd13, %rd10;
    // consume: 16 independent min ops after all loads are in flight
    min.f32 %f1, %f1, %f5;
    min.f32 %f2, %f2, %f6;
    min.f32 %f3, %f3, %f7;
    min.f32 %f4, %f4, %f8;
    min.f32 %f1, %f1, %f9;
    min.f32 %f2, %f2, %f10;
    min.f32 %f3, %f3, %f11;
    min.f32 %f4, %f4, %f12;
    min.f32 %f1, %f1, %f13;
    min.f32 %f2, %f2, %f14;
    min.f32 %f3, %f3, %f15;
    min.f32 %f4, %f4, %f16;
    min.f32 %f1, %f1, %f17;
    min.f32 %f2, %f2, %f18;
    min.f32 %f3, %f3, %f19;
    min.f32 %f4, %f4, %f20;
    add.u32 %r13, %r13, 4;
    bra UNROLL_LOOP;
REM_LOOP:
    setp.ge.u32 %p7, %r13, %r8;
    @%p7 bra STORE;
    and.b64 %rd14, %rd4, 15;
    setp.eq.u64 %p12, %rd14, 0;
    @!%p12 ld.global.f32 %f5, [%rd4];
    @!%p12 ld.global.f32 %f6, [%rd4+4];
    @!%p12 ld.global.f32 %f7, [%rd4+8];
    @!%p12 ld.global.f32 %f8, [%rd4+12];
    @%p12 ld.global.v4.f32 {%f5, %f6, %f7, %f8}, [%rd4];
    min.f32 %f1, %f1, %f5;
    min.f32 %f2, %f2, %f6;
    min.f32 %f3, %f3, %f7;
    min.f32 %f4, %f4, %f8;
    add.u64 %rd4, %rd4, %rd5;
    add.u32 %r13, %r13, 1;
    bra REM_LOOP;
PARTIAL_THREAD:
    // ragged 4-column group (n0 < inner < n0+4): per-lane predicated loads
    mov.u32 %r13, 0;                  // r = 0
PARTIAL_LOOP:
    setp.ge.u32 %p7, %r13, %r8;
    @%p7 bra STORE;
    mov.f32 %f5, 0f7F800000;
    mov.f32 %f6, 0f7F800000;
    mov.f32 %f7, 0f7F800000;
    mov.f32 %f8, 0f7F800000;
    ld.global.f32 %f5, [%rd4];        // lane 0 always valid (n0 < inner)
    @%p4 ld.global.f32 %f6, [%rd4+4];
    @%p5 ld.global.f32 %f7, [%rd4+8];
    @%p6 ld.global.f32 %f8, [%rd4+12];
    min.f32 %f1, %f1, %f5;
    min.f32 %f2, %f2, %f6;
    min.f32 %f3, %f3, %f7;
    min.f32 %f4, %f4, %f8;
    add.u64 %rd4, %rd4, %rd5;
    add.u32 %r13, %r13, 1;
    bra PARTIAL_LOOP;
STORE:
    // out[b*inner + n0 + lane] = accumulator lane (predicated if ragged)
    mul.lo.u32 %r15, %r9, %r6;
    add.u32 %r16, %r15, %r5;
    mul.wide.u32 %rd6, %r16, 4;
    add.u64 %rd7, %rd2, %rd6;
    st.global.f32 [%rd7], %f1;
    @%p4 st.global.f32 [%rd7+4], %f2;
    @%p5 st.global.f32 [%rd7+8], %f3;
    @%p6 st.global.f32 [%rd7+12], %f4;
NEXT_WORK:
    add.u32 %r24, %r24, %r22;         // w += step
    bra WORK_LOOP;
DONE:
    ret;
