_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module
_device_props_cache = {}
def _get_device_props(device):
    dev_index = device.index
    if dev_index is None:
        dev_index = torch.cuda.current_device()
    props = _device_props_cache.get(dev_index)
    if props is None:
        props = torch.cuda.get_device_properties(dev_index)
        _device_props_cache[dev_index] = props
    return props

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("min_reduce_kernel")

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        """
        Initializes the model with the dimension to reduce over.

        Args:
            dim (int): The dimension to reduce over.
        """
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        module = _get_ptx_module()

        ndim = x.dim()
        dim = self.dim
        if dim < 0:
            dim += ndim

        shape = x.shape
        outer = 1
        for i in range(dim):
            outer *= shape[i]
        R = shape[dim]
        inner = 1
        for i in range(dim + 1, ndim):
            inner *= shape[i]

        out_shape = list(shape[:dim]) + list(shape[dim + 1:])
        out = torch.empty(out_shape, dtype=x.dtype, device=x.device)

        block_x = 256
        # Each thread reduces 4 consecutive inner columns using 128-bit
        # ld.global.v4.f32 loads (with a predicated scalar fallback for
        # rows whose pointer is not 16-byte aligned), so one block
        # covers block_x * 4 columns of the inner dimension.
        items_per_block = block_x * 4
        grid_x = (inner + items_per_block - 1) // items_per_block
        total_items = outer * grid_x
        # Persistent-style launch: size the grid to an exact multiple of one
        # full wave (SMs * resident CTAs per SM) so there is no partial-wave
        # tail; the kernel grid-strides over the (outer, n-tile) work items.
        props = _get_device_props(x.device)
        blocks_per_sm = max(1, props.max_threads_per_multi_processor // block_x)
        wave_blocks = props.multi_processor_count * blocks_per_sm
        num_blocks = min(total_items, 2 * wave_blocks)
        module.launch(
            "min_reduce_kernel",
            grid=(num_blocks, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, out, u32(outer), u32(R), u32(inner)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
